#!/usr/bin/env bash
# cc-fixture-neutral-v1 (R0-05 §2.6): build MED-002 `alpha-04.mp4`
# (2 s black, 320x180, H.264, no audio, CC0, author "Course Captain Fixtures").
# PHP cannot encode H.264, so the file is committed as a build artefact;
# MED-001 (PNG), MED-003 (WebVTT) and MED-004 (PDF) are generated by
# NeutralFixture::media_files() at load time. Bit-exact flags keep the output
# stable for one ffmpeg/x264 version.
# Usage: tools/fixtures/build-media.sh
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/../.." && pwd)
OUT="$ROOT/tests/support/Fixtures/media/alpha-04.mp4"
ffmpeg -loglevel error -y -f lavfi -i color=c=black:s=320x180:d=2:r=10 \
	-c:v libx264 -preset veryslow -crf 51 -pix_fmt yuv420p \
	-map_metadata -1 -fflags +bitexact -flags:v +bitexact -movflags +faststart "$OUT"
sha256sum "$OUT"
